import struct

DST_MAC = "02:00:5e:aa:bb:cc"
SRC_MAC = "02:00:5e:11:22:33"
ETHERTYPE_IPV4 = 0x0800

def mac_to_bytes(s: str) -> bytes:
    return bytes(int(b, 16) for b in s.split(":"))

def build_frame(payload: bytes) -> bytes:
    if len(payload) < 46:
        payload += b"\x00" * (46 - len(payload))  # Ethernet minimum
    header = mac_to_bytes(DST_MAC) + mac_to_bytes(SRC_MAC)
    header += struct.pack("!H", ETHERTYPE_IPV4)
    # Real NICs append CRC-32 in hardware; we leave FCS symbolic here.
    return header + payload

def parse_frame(frame: bytes):
    dst, src, etype = struct.unpack("!6s6sH", frame[:14])
    return {
        "dst": ":".join(f"{b:02x}" for b in dst),
        "src": ":".join(f"{b:02x}" for b in src),
        "etype": hex(etype),
        "payload_len": len(frame[14:]),
    }

f = build_frame(b"hello-l3-packet")
print(parse_frame(f))
